using UPM.Windows.Core;using UPM.Windows.Transfers;
namespace UPM.Windows.Tests;
public sealed class TransferFoundationTests {
 [Fact] public void IdentityIsStableAndSensitiveToFileRevision(){var profile=Guid.NewGuid();var t=DateTimeOffset.UtcNow;Assert.Equal(TransferIdentity.Create(profile,null,"a.pptx",5,t),TransferIdentity.Create(profile,null,"a.pptx",5,t));Assert.NotEqual(TransferIdentity.Create(profile,null,"a.pptx",5,t),TransferIdentity.Create(profile,null,"a.pptx",6,t));}
 [Fact] public async Task DirectoryEnumerationPreservesRelativePathsAndFiltersTempFiles(){var root=Directory.CreateTempSubdirectory();try{Directory.CreateDirectory(Path.Combine(root.FullName,"Room A"));await File.WriteAllTextAsync(Path.Combine(root.FullName,"Room A","deck.pptx"),"test");await File.WriteAllTextAsync(Path.Combine(root.FullName,"Room A","notes.txt"),"test");var rows=new List<TransferItem>();await foreach(var row in IntakeEnumerator.EnumerateAsync([root.FullName],Guid.NewGuid(),null))rows.Add(row);Assert.Single(rows);Assert.Equal(Path.Combine("Room A","deck.pptx"),rows[0].RelativePath);}finally{root.Delete(true);}}
 [Fact] public async Task QueueSurvivesStoreReopenAndDeduplicates(){var root=Directory.CreateTempSubdirectory();try{var db=Path.Combine(root.FullName,"state.db");var store=new LocalStateStore(db);await store.InitializeAsync();var now=DateTimeOffset.UtcNow;var item=new TransferItem(Guid.NewGuid(),Guid.NewGuid(),null,"x.pptx","x.pptx","x.pptx",null,1,now,"stable-key");await store.EnqueueAsync(item);await new LocalStateStore(db).InitializeAsync();await store.EnqueueAsync(item with{TransferId=Guid.NewGuid()});Assert.True(File.Exists(db));}finally{root.Delete(true);}}
}
